    ItemCard(english: "You hit the nail on the head.", arabic: "لقد أصبت كبد الحقيقة."),
    ItemCard(english: "He visits us once in a blue moon.", arabic: "هو يزورنا نادراً جداً."),
    ItemCard(english: "I'm feeling under the weather today.", arabic: "أشعر أنني متوعك اليوم."),
    ItemCard(english: "I want to settle the score with him.", arabic: "أريد أن أسوّي حسابي معه."),
    ItemCard(english: "He is in a tight spot right now.", arabic: "هو في موقف صعب الآن."),

    // ===== إضافات - جمل متنوعة =====
    ItemCard(english: "I hate waking up early on weekends.", arabic: "أكره الاستيقاظ مبكراً في عطلة نهاية الأسبوع."),
    ItemCard(english: "She loves the smell of rain.", arabic: "هي تحب رائحة المطر."),
    ItemCard(english: "He dislikes waiting in long lines.", arabic: "هو لا يحب الانتظار في طوابير طويلة."),
    ItemCard(english: "The food here is absolutely delicious.", arabic: "الطعام هنا لذيذ تماماً."),
    ItemCard(english: "I'm completely exhausted today.", arabic: "أنا منهك تماماً اليوم."),
    ItemCard(english: "She is definitely the best candidate.", arabic: "هي بالتأكيد أفضل مرشحة."),
    ItemCard(english: "That's exactly what I meant.", arabic: "هذا بالضبط ما قصدته."),
    ItemCard(english: "I hardly ever eat fast food.", arabic: "نادراً ما آكل الوجبات السريعة."),
    ItemCard(english: "He rarely complains about anything.", arabic: "هو نادراً ما يتذمر من أي شيء."),
    ItemCard(english: "We occasionally go to the cinema.", arabic: "نحن نذهب إلى السينما بين الحين والآخر."),
    ItemCard(english: "She frequently visits her grandmother.", arabic: "هي تزور جدتها بشكل متكرر."),
    ItemCard(english: "I usually drink tea in the morning.", arabic: "عادةً أشرب الشاي في الصباح."),
    ItemCard(english: "He normally arrives at 9 am.", arabic: "هو عادةً يصل الساعة 9 صباحاً."),
    ItemCard(english: "Generally, I prefer coffee over tea.", arabic: "عموماً، أفضل القهوة على الشاي."),
    ItemCard(english: "Especially in winter, I love hot drinks.", arabic: "خاصةً في الشتاء، أحب المشروبات الساخنة."),
    ItemCard(english: "Mostly, we stay home on Fridays.", arabic: "في الغالب، نبقى في المنزل أيام الجمعة."),
    ItemCard(english: "Mainly, I work from home.", arabic: "بشكل رئيسي، أعمل من المنزل."),
    ItemCard(english: "I partially agree with you.", arabic: "أنا أتفق معك جزئياً."),
    ItemCard(english: "She totally ignored my message.", arabic: "هي تجاهلت رسالتي كلياً."),
    ItemCard(english: "I absolutely love this song.", arabic: "أنا أحب هذه الأغنية إطلاقاً."),
    ItemCard(english: "He almost missed the train.", arabic: "هو كاد يفوت القطار."),
    ItemCard(english: "I barely finished my homework.", arabic: "بالكاد أنهيت واجبي."),
    ItemCard(english: "There were nearly 100 people at the party.", arabic: "كان هناك ما يقرب من 100 شخص في الحفلة."),
    ItemCard(english: "Unfortunately, I can't come today.", arabic: "لسوء الحظ، لا أستطيع القدوم اليوم."),
    ItemCard(english: "Luckily, nobody was hurt.", arabic: "لحسن الحظ، لم يُصب أحد."),
    ItemCard(english: "Finally, we arrived at the hotel.", arabic: "أخيراً، وصلنا إلى الفندق."),
    ItemCard(english: "Recently, I started learning English.", arabic: "مؤخراً، بدأت تعلم الإنجليزية."),
    ItemCard(english: "Nowadays, everyone uses smartphones.", arabic: "في الوقت الحالي، الجميع يستخدم الهواتف الذكية."),
    ItemCard(english: "From now on, I will exercise every day.", arabic: "من الآن فصاعداً، سأتمرن كل يوم."),
    ItemCard(english: "In the past, people wrote letters.", arabic: "في الماضي، كان الناس يكتبون الرسائل."),
    ItemCard(english: "At last, I found my keys!", arabic: "أخيراً، وجدت مفاتيحي!"),
  ];

  @override
  Widget build(BuildContext context) {
    return GenericListScreen(
      title: "Awful Smell - جميع الجمل",
      items: sentences,
      primaryColor: ColorManager.celestial2,
      secondaryColor: Color(0xFF203A43),
    );
  }
}


