class VeryBadDayCompleteSentencesScreen extends StatelessWidget {
  final List<ItemCard> sentences = [
    // ===== جمل من Exercise 1 =====
    ItemCard(english: "Nancy regrets saying mean things to her brother when he broke her favorite pot.", arabic: "نانسي تندم على قول أشياء لئيمة لأخيها عندما كسر قدرها المفضل."),
    ItemCard(english: "Would you pour me a tall glass of chocolate milk, please?", arabic: "هل تصب لي كوباً طويلاً من حليب الشوكولاتة، من فضلك؟"),
    ItemCard(english: "Why did you throw your cat into the water? Are you crazy?", arabic: "لماذا رميت قطتك في الماء؟ هل أنت مجنون؟"),
    ItemCard(english: "Could you wait a moment? I have to shut the window before we go out.", arabic: "هل يمكنك الانتظار لحظة؟ يجب أن أغلق النافذة قبل أن نخرج."),
    ItemCard(english: "You should not steal your friend's toys. It is wrong.", arabic: "لا يجب أن تسرق ألعاب صديقك. هذا خطأ."),

    // ===== جمل من Exercise 2 =====
    ItemCard(english: "Julie forgot to mention that her brother was in the movie.", arabic: "جولي نسيت أن تذكر أن أخاها كان في الفيلم."),
    ItemCard(english: "The boy intended to run in the race, but he broke his leg.", arabic: "الولد كان ينوي الجري في السباق، لكنه كسر ساقه."),
    ItemCard(english: "Oh, I didn't want extra cheese on my pizza. Can you take it off, please?", arabic: "أوه، لم أرد جبنة إضافية على البيتزا. هل يمكنك نزعها، من فضلك؟"),
    ItemCard(english: "Mike! You need to stop fighting with your brother immediately.", arabic: "مايك! يجب أن تتوقف عن القتال مع أخيك فوراً."),
    ItemCard(english: "Chris got the ball and scored the winning goal. Everyone cheered for him.", arabic: "كريس حصل على الكرة وسجل هدف الفوز. الجميع هتف له."),

    // ===== جمل من قصة "A Very Bad Day" =====
    ItemCard(english: "Today was awful. I intended to go to soccer practice.", arabic: "اليوم كان بشعاً. كنت أنوي الذهاب إلى تمرين كرة القدم."),
    ItemCard(english: "The coach mentioned that he wanted me to score more points.", arabic: "المدرب ذكر أنه يريدني أن أسجل نقاطاً أكثر."),
    ItemCard(english: "I needed extra practice. I did not get the chance to practice.", arabic: "كنت أحتاج تمريناً إضافياً. لم أحصل على الفرصة للتدرب."),
    ItemCard(english: "Someone stole my soccer shoes! I searched everywhere but could not find them.", arabic: "شخص ما سرق حذاء كرة القدم الخاص بي! بحثت في كل مكان لكن لم أستطع إيجاده."),
    ItemCard(english: "I felt even worse because they were new. I really regretted bringing them.", arabic: "شعرت بأسوأ لأنها كانت جديدة. ندمت حقاً على إحضارها."),
    ItemCard(english: "When I saw that the shoes were missing, I went to my coach immediately.", arabic: "عندما رأيت أن الحذاء مفقود، ذهبت إلى مدربي فوراً."),
    ItemCard(english: "His reaction was calm. He did not think it was odd for someone to steal my shoes.", arabic: "ردة فعله كانت هادئة. لم يعتقد أنه غريب أن يسرق شخص حذائي."),
    ItemCard(english: "He said it happened a lot, and he would find the thief and make him return my shoes.", arabic: "قال إنها تحدث كثيراً، وسيجد اللص ويجعله يُرجع حذائي."),
    ItemCard(english: "I watched my team practice. Our players are not huge, but we are all tough.", arabic: "شاهدت فريقي يتدرب. لاعبونا ليسوا ضخاماً، لكننا كلنا أقوياء."),
    ItemCard(english: "I cannot wait to get my shoes back and play again.", arabic: "لا أستطيع الانتظار لاستعادة حذائي واللعب مرة أخرى."),

    // ===== جمل من Exercise 1 (Choose the correct word) =====
    ItemCard(english: "Ryan is a big and tough basketball player. He is the best on our team.", arabic: "رايان لاعب كرة سلة كبير وقوي. هو الأفضل في فريقنا."),
    ItemCard(english: "The accident on the busy road was awful. Many people were hurt.", arabic: "الحادث على الطريق المزدحم كان بشعاً. كثير من الناس أصيبوا."),
    ItemCard(english: "Maggie found several odd insects on the ground on her way home.", arabic: "ماجي وجدت عدة حشرات غريبة على الأرض في طريقها للمنزل."),
    ItemCard(english: "We cannot take the stairs to the top of the huge building.", arabic: "لا يمكننا صعود السلالم إلى قمة المبنى الضخم."),
    ItemCard(english: "The thief used a long rope to get down from the house.", arabic: "اللص استخدم حبلاً طويلاً لينزل من المنزل."),

    // ===== إضافات جديدة - جمل مع Tough =====
    ItemCard(english: "This math problem is really tough.", arabic: "مسألة الرياضيات هذه صعبة حقاً."),
    ItemCard(english: "He is a tough player, but he is fair.", arabic: "هو لاعب قوي، لكنه عادل."),
    ItemCard(english: "Life can be tough sometimes.", arabic: "الحياة يمكن أن تكون صعبة أحياناً."),

    // ===== إضافات جديدة - جمل مع Main =====
    ItemCard(english: "This is the main entrance of the building.", arabic: "هذا هو المدخل الرئيسي للمبنى."),
