    // ===== إضافات جديدة - جمل مع Sore =====
    ItemCard(english: "My throat is sore. I think I'm sick.", arabic: "حلقي مؤلم. أعتقد أنني مريض."),
    ItemCard(english: "She has a sore back from sitting too long.", arabic: "ظهرها مؤلم من الجلوس الطويل."),
