    // ===== إضافات جديدة - جمل مع Calm =====
    ItemCard(english: "Please stay calm and don't panic.", arabic: "من فضلك ابقَ هادئاً ولا تذعر."),
    ItemCard(english: "The sea is calm today.", arabic: "البحر هادئ اليوم."),
