    // ===== إضافات جديدة - جمل مع Extra =====
    ItemCard(english: "I need extra time to finish this.", arabic: "أحتاج وقتاً إضافياً لإنهاء هذا."),
    ItemCard(english: "She asked for extra cheese on her pizza.", arabic: "هي طلبت جبنة إضافية على البيتزا."),
    ItemCard(english: "We have extra chairs in the garage.", arabic: "لدينا كراسي إضافية في المرآب."),

    // ===== إضافات جديدة - جمل مع Coach / Team =====
    ItemCard(english: "Our coach is very strict but fair.", arabic: "مدربنا صارم جداً لكنه عادل."),
    ItemCard(english: "The team practiced for three hours.", arabic: "الفريق تدرب لمدة ثلاث ساعات."),
    ItemCard(english: "Every player on the team is important.", arabic: "كل لاعب في الفريق مهم."),

    // ===== إضافات جديدة - جمل مع Score =====
    ItemCard(english: "He scored two goals in the first half.", arabic: "هو سجل هدفين في الشوط الأول."),
    ItemCard(english: "Who scored the first point?", arabic: "من سجل النقطة الأولى؟"),
    ItemCard(english: "Our team scored the winning goal in the last minute.", arabic: "فريقنا سجل هدف الفوز في الدقيقة الأخيرة."),

    // ===== إضافات جديدة - جمل مع Chance =====
    ItemCard(english: "This is your last chance to try.", arabic: "هذه فرصتك الأخيرة للمحاولة."),
    ItemCard(english: "I didn't get the chance to say goodbye.", arabic: "لم أحصل على الفرصة لأقول وداعاً."),
    ItemCard(english: "Give him a chance to explain.", arabic: "أعطه فرصة ليشرح."),

    // ===== إضافات جديدة - جمل مع Moment =====
    ItemCard(english: "Wait a moment, please.", arabic: "انتظر لحظة، من فضلك."),
    ItemCard(english: "This is a special moment for us.", arabic: "هذه لحظة خاصة لنا."),
    ItemCard(english: "I'll be there in a moment.", arabic: "سأكون هناك في لحظة."),

    // ===== إضافات جديدة - جمل مع Regret =====
    ItemCard(english: "I regret not studying harder for the exam.", arabic: "أنا نادم على عدم دراستي بجدية أكبر للامتحان."),
    ItemCard(english: "She regrets buying that expensive bag.", arabic: "هي نادمة على شراء تلك الحقيبة الغالية."),
    ItemCard(english: "You will regret this decision.", arabic: "سوف تندم على هذا القرار."),
    ItemCard(english: "He regretted saying those words.", arabic: "هو ندم على قول تلك الكلمات."),

    // ===== إضافات جديدة - جمل مع Reaction =====
    ItemCard(english: "His reaction to the news was surprising.", arabic: "ردة فعله على الخبر كانت مفاجئة."),
    ItemCard(english: "What was her reaction to the gift?", arabic: "ما كانت ردة فعلها على الهدية؟"),
    ItemCard(english: "I didn't expect such a calm reaction.", arabic: "لم أتوقع ردة فعل هادئة كهذه."),

    // ===== إضافات جديدة - جمل مع Worse =====
    ItemCard(english: "The weather is getting worse.", arabic: "الطقس يزداد سوءاً."),
    ItemCard(english: "It could be worse. Don't worry.", arabic: "كان يمكن أن يكون أسوأ. لا تقلق."),
    ItemCard(english: "This is worse than I expected.", arabic: "هذا أسوأ مما توقعت."),

    // ===== إضافات جديدة - جمل مع Odd =====
    ItemCard(english: "It's odd that he didn't come to the party.", arabic: "من الغريب أنه لم يأت إلى الحفلة."),
    ItemCard(english: "She has an odd way of speaking.", arabic: "لديها طريقة غريبة في الكلام."),
    ItemCard(english: "The odd thing is that nobody noticed.", arabic: "الشيء الغريب أن لا أحد لاحظ."),

    // ===== إضافات جديدة - جمل مع Brave =====
    ItemCard(english: "The firefighter was very brave.", arabic: "رجل الإطفاء كان شجاعاً جداً."),
    ItemCard(english: "It was brave of you to speak up.", arabic: "كان شجاعاً منك أن تتكلم."),
    ItemCard(english: "She is brave enough to face her fears.", arabic: "هي شجاعة بما يكفي لمواجهة مخاوفها."),

    // ===== إضافات جديدة - جمل مع Awful =====
    ItemCard(english: "The food at that restaurant was awful.", arabic: "الطعام في ذلك المطعم كان بشعاً."),
    ItemCard(english: "I had an awful headache yesterday.", arabic: "كان لدي صداع بشع أمس."),
    ItemCard(english: "The traffic this morning was awful.", arabic: "الزحمة هذا الصباح كانت بشعة."),

    // ===== إضافات جديدة - جمل مع Huge =====
    ItemCard(english: "They live in a huge house.", arabic: "هم يعيشون في منزل ضخم."),
    ItemCard(english: "There is a huge difference between the two.", arabic: "هناك فرق ضخم بين الاثنين."),
    ItemCard(english: "The elephant is a huge animal.", arabic: "الفيل حيوان ضخم."),

    // ===== إضافات جديدة - جمل متنوعة =====
    ItemCard(english: "The thief stole the money and ran away.", arabic: "اللص سرق المال وهرب."),
    ItemCard(english: "I searched everywhere for my missing phone.", arabic: "بحثت في كل مكان عن هاتفي المفقود."),
    ItemCard(english: "The coach was calm after the loss.", arabic: "المدرب كان هادئاً بعد الخسارة."),
    ItemCard(english: "Our team is tough and never gives up.", arabic: "فريقنا قوي ولا يستسلم أبداً."),
    ItemCard(english: "I need extra practice to improve my skills.", arabic: "أحتاج تمريناً إضافياً لتحسين مهاراتي."),
    ItemCard(english: "She got the chance to meet her favorite singer.", arabic: "حصلت على الفرصة لمقابلة مغنيها المفضل."),
    ItemCard(english: "His reaction to the accident was very calm.", arabic: "ردة فعله على الحادث كانت هادئة جداً."),
    ItemCard(english: "I regretted not bringing my umbrella.", arabic: "ندمت على عدم إحضار مظلتي."),
    ItemCard(english: "The situation got worse before it got better.", arabic: "الوضع ازداد سوءاً قبل أن يتحسن."),
    ItemCard(english: "It was odd to see him so quiet.", arabic: "كان غريباً رؤيته هادئاً جداً."),
    ItemCard(english: "She was brave to speak in front of everyone.", arabic: "كانت شجاعة لتتحدث أمام الجميع."),
    ItemCard(english: "The building is huge and modern.", arabic: "المبنى ضخم وحديث."),
    ItemCard(english: "I poured myself a cup of tea.", arabic: "صبيت لنفسي كوباً من الشاي."),
    ItemCard(english: "Wait a moment, I'm almost ready.", arabic: "انتظر لحظة، أنا تقريباً جاهز."),
  ];

  @override
  Widget build(BuildContext context) {
    return GenericListScreen(
      title: "A Very Bad Day - جميع الجمل",
      items: sentences,
      primaryColor: ColorManager.celestial2,
      secondaryColor: Color(0xFF203A43),
    );
  }
}


