    ItemCard(english: "My father supplies carrots to restaurants in our town.", arabic: "والدي يزود مطاعم مدينتنا بالجزر."),

    // ===== إضافات - جمل مع Bit / Piece =====
    ItemCard(english: "I ate a bit of cake.", arabic: "أكلت قطعة صغيرة من الكيك."),
    ItemCard(english: "She gave me a bit of advice.", arabic: "هي أعطتني قليلاً من النصيحة."),
    ItemCard(english: "I'm a bit tired today.", arabic: "أنا متعب قليلاً اليوم."),
    ItemCard(english: "Cut the apple into small bits.", arabic: "قطع التفاحة إلى قطع صغيرة."),
    ItemCard(english: "He broke the glass into bits.", arabic: "هو كسر الكوب إلى قطع."),

    // ===== إضافات - جمل مع Common =====
    ItemCard(english: "It's common to feel nervous before an exam.", arabic: "من الشائع الشعور بالتوتر قبل الامتحان."),
    ItemCard(english: "This is a common mistake among students.", arabic: "هذا خطأ شائع بين الطلاب."),
    ItemCard(english: "Headaches are common when you don't sleep well.", arabic: "الصداع شائع عندما لا تنام جيداً."),
    ItemCard(english: "Cats are common pets in many homes.", arabic: "القطط حيوانات أليفة شائعة في كثير من المنازل."),

    // ===== إضافات - جمل مع Diet =====
