    ItemCard(english: "The company supplies water to the city.", arabic: "الشركة تزود المدينة بالماء."),
    ItemCard(english: "My father supplies vegetables to restaurants.", arabic: "والدي يزود المطاعم بالخضروات."),
    ItemCard(english: "They supply fresh bread every morning.", arabic: "هم يزودون بالخبز الطازج كل صباح."),

    // ===== إضافات - جمل متنوعة =====
    ItemCard(english: "I'm a bit hungry. Let's get something to eat.", arabic: "أنا جائع قليلاً. لنأكل شيئاً."),
    ItemCard(english: "It's common to make mistakes when learning.", arabic: "من الشائع ارتكاب أخطاء عند التعلم."),
    ItemCard(english: "A healthy diet and exercise are both important.", arabic: "النظام الغذائي الصحي والتمرين كلاهما مهم."),
    ItemCard(english: "He stays fit by playing football.", arabic: "هو يبقى لائقاً بلعب كرة القدم."),
    ItemCard(english: "You should limit your time on social media.", arabic: "يجب أن تحدد وقتك على وسائل التواصل الاجتماعي."),
    ItemCard(english: "Physical health is as important as mental health.", arabic: "الصحة الجسدية مهمة مثل الصحة النفسية."),
    ItemCard(english: "The evidence shows that he is guilty.", arabic: "الدليل يظهر أنه مذنب."),
    ItemCard(english: "The house is for sale at a good price.", arabic: "المنزل للبيع بسعر جيد."),
    ItemCard(english: "Add the right amount of sugar to the tea.", arabic: "أضف الكمية المناسبة من السكر إلى الشاي."),
    ItemCard(english: "The cure for this disease was discovered recently.", arabic: "علاج هذا المرض تم اكتشافه مؤخراً."),
    ItemCard(english: "The disease affected many people in the area.", arabic: "المرض أصاب كثير من الناس في المنطقة."),
    ItemCard(english: "Be careful! That bottle contains poison.", arabic: "كن حذراً! تلك الزجاجة تحتوي على سم."),
    ItemCard(english: "What type of food do you prefer?", arabic: "ما نوع الطعام الذي تفضله؟"),
    ItemCard(english: "This is a serious matter. We need to discuss it.", arabic: "هذا أمر خطير. نحتاج لمناقشته."),
    ItemCard(english: "She received medical treatment at the hospital.", arabic: "هي تلقت علاجاً طبياً في المستشفى."),
    ItemCard(english: "It's necessary to wear a seatbelt in the car.", arabic: "من الضروري ارتداء حزام الأمان في السيارة."),
    ItemCard(english: "The government reduced taxes this year.", arabic: "الحكومة خفضت الضرائب هذا العام."),
    ItemCard(english: "The farm supplies fresh vegetables to the market.", arabic: "المزرعة تزود السوق بالخضروات الطازجة."),
  ];

  @override
  Widget build(BuildContext context) {
    return GenericListScreen(
      title: "Bit & Common - جميع الجمل",
      items: sentences,
      primaryColor: ColorManager.celestial2,
      secondaryColor: Color(0xFF203A43),
    );
  }
}


