    ItemCard(english: "Medical describes something that has to do with doctors.", arabic: "طبي تصف شيئاً له علاقة بالأطباء."),
    ItemCard(english: "Good health is necessary for happiness.", arabic: "الصحة الجيدة ضرورية للسعادة."),
