    ItemCard(english: "I try to avoid junk food and eat more vegetables.", arabic: "أحاول تجنب الوجبات السريعة وأكل المزيد من الخضروات."),
    ItemCard(english: "Candy and cookies are types of junk food.", arabic: "الحلوى والبسكويت أنواع من الوجبات السريعة."),
    ItemCard(english: "A healthy diet includes fruits and vegetables.", arabic: "النظام الغذائي الصحي يشمل الفواكه والخضروات."),
    ItemCard(english: "He needs to change his diet to lose weight.", arabic: "هو يحتاج لتغيير نظامه الغذائي لإنقاص الوزن."),

    // ===== إضافات - جمل مع Produce / Supply =====
    ItemCard(english: "This factory produces 500 cars a day.", arabic: "هذا المصنع ينتج 500 سيارة يومياً."),
    ItemCard(english: "The farm supplies fresh vegetables to the market.", arabic: "المزرعة تزود السوق بالخضروات الطازجة."),
    ItemCard(english: "Brazil produces a lot of coffee.", arabic: "البرازيل تنتج الكثير من القهوة."),
