    // ===== إضافات - جمل مع Reduce / Limit =====
    ItemCard(english: "We need to reduce our use of plastic.", arabic: "نحتاج لتقليل استخدامنا للبلاستيك."),
    ItemCard(english: "I limit my time on social media to one hour a day.", arabic: "أحدد وقتي على وسائل التواصل بساعة واحدة يومياً."),
    ItemCard(english: "Reduce the amount of sugar you eat.", arabic: "قلل كمية السكر التي تأكلها."),
    ItemCard(english: "The store reduced its prices last week.", arabic: "المتجر خفض أسعاره الأسبوع الماضي."),

    // ===== إضافات - جمل مع Poison / Disease =====
    ItemCard(english: "Too much sugar is like poison to your body.", arabic: "الكثير من السكر يشبه السم لجسمك."),
    ItemCard(english: "Some plants contain poison.", arabic: "بعض النباتات تحتوي على سم."),
    ItemCard(english: "Bad diets can cause serious diseases.", arabic: "الأنظمة الغذائية السيئة يمكن أن تسبب أمراضاً خطيرة."),
