    ItemCard(english: "Good health is necessary for a happy life.", arabic: "الصحة الجيدة ضرورية لحياة سعيدة."),
    ItemCard(english: "Medical help is necessary in an emergency.", arabic: "المساعدة الطبية ضرورية في حالات الطوارئ."),
    ItemCard(english: "A bit of sugar makes the tea sweeter.", arabic: "قليل من السكر يجعل الشاي أحلى."),
    ItemCard(english: "Asia produces a large amount of rice.", arabic: "آسيا تنتج كمية كبيرة من الأرز."),
    ItemCard(english: "Ellen was the best source of ideas in our group.", arabic: "إلين كانت أفضل مصدر للأفكار في مجموعتنا."),
    ItemCard(english: "Germany produces a lot of popular cars.", arabic: "ألمانيا تنتج الكثير من السيارات الشهيرة."),
    ItemCard(english: "The new cure will save many people's lives.", arabic: "العلاج الجديد سينقذ حياة الكثيرين."),
    ItemCard(english: "We can reduce the amount of soda we drink.", arabic: "يمكننا تقليل كمية الصودا التي نشربها."),
    ItemCard(english: "Some schools have stopped selling soda at lunch.", arabic: "بعض المدارس أوقفت بيع الصودا عند الغداء."),
    ItemCard(english: "You can eat a bit of junk food sometimes.", arabic: "يمكنك أكل قليل من الوجبات السريعة أحياناً."),
    ItemCard(english: "Just don't eat junk food every day!", arabic: "فقط لا تأكل الوجبات السريعة كل يوم!"),
    ItemCard(english: "The Earth is getting warmer because of pollution.", arabic: "الأرض تزداد حرارة بسبب التلوث."),
    ItemCard(english: "Kids today are less fit than in the past.", arabic: "الأطفال اليوم أقل ليونة من الماضي."),
    ItemCard(english: "Bad diets can cause diseases with no cure.", arabic: "الأنظمة الغذائية السيئة يمكن أن تسبب أمراضاً بلا علاج."),
    ItemCard(english: "Listening to music is a common hobby.", arabic: "الاستماع للموسيقى هواية شائعة."),
    ItemCard(english: "The plan is not carved in stone yet.", arabic: "الخطة ليست منقوشة على الحجر بعد."),
  ];

  @override
  Widget build(BuildContext context) {
    return GenericListScreen(
      title: "Episode 4 - جميع الجمل",
      items: sentences,
      primaryColor: ColorManager.celestial2,
      secondaryColor: Color(0xFF203A43),
    );
  }
}



