class Episode5CompleteSentencesScreen extends StatelessWidget {
  final List<ItemCard> sentences = [
    // ===== جمل من الكتاب =====
    ItemCard(english: "It was common to find huge castles in the past.", arabic: "كان من الشائع أن تجد القلاع الضخمة في الماضي."),
    ItemCard(english: "Tim made a decision to eat carrots to be healthier.", arabic: "اتخذ تيم قراراً لتناول الجزر ليكون أكثر صحة."),
