    ItemCard(english: "They serve many types of food at this restaurant.", arabic: "أنهم يقدمون أنواع عديدة من الطعام في هذا المطعم."),
    ItemCard(english: "For beautiful skin, a healthy diet and good habits are necessary.", arabic: "من أجل بشرة جميلة، من الضروري اتباع نظام غذائي صحي وعادات جيدة."),
    ItemCard(english: "I admire my father more than anyone else.", arabic: "أنا معجب بأبي أكثر من أي شخص آخر."),
    ItemCard(english: "This city in Peru is evidence of an ancient culture.", arabic: "هذه المدينة في بيرو هي دليل على وجود حضارة قديمة."),
