    ItemCard(english: "If I had known the poor quality of this phone, I would not have bought it.", arabic: "لو كنت أعرف الجودة السيئة لهذا الهاتف، لما اشتريته."),
    ItemCard(english: "The clever thief had stolen many paintings before anyone found out.", arabic: "اللص الذكي سرق لوحات كثيرة قبل أن يكتشف أحد."),
    ItemCard(english: "What is the length of these pants?", arabic: "ما هو طول هذا البنطال؟"),
    ItemCard(english: "She regularly flies to southern Australia for meetings.", arabic: "هي تطير بانتظام إلى جنوب أستراليا للاجتماعات."),
    ItemCard(english: "You can easily find any book title by searching the internet.", arabic: "يمكنك بسهولة إيجاد عنوان أي كتاب بالبحث على الإنترنت."),
    ItemCard(english: "Polly and Cliff are my favorite TV characters.", arabic: "بولي وكليف هما شخصيتاي التلفزيونية المفضلتان."),
    ItemCard(english: "Susan was my enemy until we became friends in 6th grade.", arabic: "سوزان كانت عدوتي حتى أصبحنا أصدقاء في الصف السادس."),
    ItemCard(english: "Gretchen has promised to explore the castle and park with me.", arabic: "غريتشين وعدت باستكشاف القلعة والحديقة معي."),
  ];

  @override
  Widget build(BuildContext context) {
    return GenericListScreen(
      title: "Episode 8 - جميع الجمل",
      items: sentences,
      primaryColor: ColorManager.celestial2,
      secondaryColor: Color(0xFF203A43),
    );
  }
}



