    ItemCard(english: "The washing machine is making a strange noise.", arabic: "الغسالة تصدر صوتاً غريباً."),
    ItemCard(english: "She rubbed the lotion on her skin.", arabic: "هي فركت اللوشن على بشرتها."),
    ItemCard(english: "The moon shines brightly tonight.", arabic: "القمر يلمع بشكل ساطع الليلة."),
    ItemCard(english: "Building strength takes time and effort.", arabic: "بناء القوة يحتاج وقتاً وجهداً."),
    ItemCard(english: "I suggest you see a doctor about that cough.", arabic: "أقترح أن ترى طبيباً بشأن ذلك السعال."),
    ItemCard(english: "The tour of the castle lasted two hours.", arabic: "جولة القلعة استمرت ساعتين."),
    ItemCard(english: "The wheel is one of the greatest inventions.", arabic: "العجلة من أعظم الاختراعات."),
    ItemCard(english: "The children were curious about the new teacher.", arabic: "الأطفال كانوا فضوليين بشأن المعلم الجديد."),
    ItemCard(english: "The sun disappeared behind the mountains.", arabic: "الشمس اختفت خلف الجبال."),
    ItemCard(english: "He stood at the edge of the water.", arabic: "هو وقف على حافة الماء."),
    ItemCard(english: "The guide spoke three languages.", arabic: "المرشد كان يتحدث ثلاث لغات."),
    ItemCard(english: "Local products are usually fresher.", arabic: "المنتجات المحلية عادةً أكثر طزاجة."),
    ItemCard(english: "This machine can do the work of ten people.", arabic: "هذه الآلة يمكنها عمل عشرة أشخاص."),
    ItemCard(english: "She rubbed her hands to warm them.", arabic: "هي فركت يديها لتدفئتهما."),
    ItemCard(english: "The diamond shines in the light.", arabic: "الألماسة تلمع في الضوء."),
    ItemCard(english: "His strength surprised everyone.", arabic: "قوته فاجأت الجميع."),
    ItemCard(english: "I suggest we leave early to avoid traffic.", arabic: "أقترح أن نغادر مبكراً لتجنب الزحام."),
    ItemCard(english: "We took a tour around the old city.", arabic: "أخذنا جولة حول المدينة القديمة."),
    ItemCard(english: "The wheels of the bus go round and round.", arabic: "عجلات الباص تدور وتدور."),
  ];

  @override
  Widget build(BuildContext context) {
    return GenericListScreen(
      title: "Episode 9 - جميع الجمل",
      items: sentences,
      primaryColor: ColorManager.celestial2,
      secondaryColor: Color(0xFF203A43),
    );
  }
}


