class Episode10CompleteSentencesScreen extends StatelessWidget {
  final List<ItemCard> sentences = [
    // ===== جمل من قصة "A Bus Tour" =====
    ItemCard(english: "We met in a big crowd by the buses outside the hotel.", arabic: "التقينا في حشد كبير بجانب الباصات خارج الفندق."),
    ItemCard(english: "Everyone was curious about the tour and expected it to be a lot of fun.", arabic: "كان الجميع فضوليين بشأن الجولة وتوقعوا أن تكون ممتعة جداً."),
    ItemCard(english: "Dmitry, a native of Russia, was our guide.", arabic: "ديمتري، مواطن من روسيا، كان مرشدنا."),
    ItemCard(english: "He suggested that we take a lot of pictures.", arabic: "هو اقترح أن نلتقط الكثير من الصور."),
    ItemCard(english: "He also explained that there would be many places to shop.", arabic: "هو أيضاً شرح أنه سيكون هناك أماكن كثيرة للتسوق."),
    ItemCard(english: "'Oh, no!' the bus driver said. We had stopped on an avenue in a small western town.", arabic: "'أوه، لا!' قال سائق الباص. توقفنا في شارع في بلدة غربية صغيرة."),
    ItemCard(english: "One of the bus's wheels needed to be fixed.", arabic: "إحدى عجلات الباص كانت تحتاج إلى إصلاح."),
    ItemCard(english: "'We will look around for a while,' Dmitry said.", arabic: "'سنتجول لبعض الوقت'، قال ديمتري."),
    ItemCard(english: "Some of the local stores were open, and we were able to shop for things.", arabic: "بعض المتاجر المحلية كانت مفتوحة، وكنا قادرين على التسوق."),
    ItemCard(english: "The sun was shining so it was nice to walk around.", arabic: "كانت الشمس مشرقة فكان من اللطيف التجول."),
    ItemCard(english: "When the bus was ready, we got back on and continued the tour.", arabic: "عندما كان الباص جاهزاً، صعدنا مرة أخرى وأكملنا الجولة."),

    // ===== جمل من Exercise 1 =====
    ItemCard(english: "The smoke caused me to cough badly.", arabic: "الدخان جعلني أسعل بشدة."),
    ItemCard(english: "Mrs. Mackey was curious about what we did on vacation.", arabic: "السيدة ماكي كانت فضولية بشأن ما فعلناه في العطلة."),
    ItemCard(english: "We could not see Ronald because he disappeared in the crowd.", arabic: "لم نستطع رؤية رونالد لأنه اختفى في الحشد."),
    ItemCard(english: "Sabrina regularly worked as a guide for the hotel.", arabic: "سابرينا عملت بانتظام كمرشدة للفندق."),
    ItemCard(english: "It was clever of you to build this helpful machine.", arabic: "كان ذكياً منك أن تبني هذه الآلة المفيدة."),

    // ===== جمل من Exercise 2 =====
    ItemCard(english: "Hans burned his food, causing a lot of smoke in the kitchen.", arabic: "هانز حرق طعامه، مما سبب الكثير من الدخان في المطبخ."),
    ItemCard(english: "I cannot imagine how big the crowd will be at the baseball game.", arabic: "لا أستطيع تخيل كم سيكون الحشد كبيراً في مباراة البيسبول."),
    ItemCard(english: "I am a native of Canada, but I have not lived there for a long time.", arabic: "أنا مواطن من كندا، لكنني لم أعش هناك لفترة طويلة."),
    ItemCard(english: "I viewed the street below from the edge of the roof of the tall building.", arabic: "شاهدت الشارع بالأسفل من حافة سطح المبنى العالي."),
    ItemCard(english: "We have discovered a restaurant which serves food grown by local farmers.", arabic: "اكتشفنا مطعماً يقدم طعاماً مزروعاً من مزارعين محليين."),

    // ===== جمل من Exercise 3 =====
    ItemCard(english: "Ben tried to explain the math problem to his friend.", arabic: "بن حاول أن يشرح مسألة الرياضيات لصديقه."),
    ItemCard(english: "Bree rubbed her head after she fell and hit it on the ground.", arabic: "بري فركت رأسها بعد أن سقطت وضربته بالأرض."),
    ItemCard(english: "The tour included a visit to a small village near the mountains in Peru.", arabic: "الجولة شملت زيارة إلى قرية صغيرة قرب جبال في بيرو."),
    ItemCard(english: "Excuse me. Can you suggest a good restaurant for fish nearby?", arabic: "عفواً. هل يمكنك اقتراح مطعم جيد للسمك قريب؟"),
    ItemCard(english: "Which avenue does your grandmother live on? I want to find it on the map.", arabic: "في أي شارع تسكن جدتك؟ أريد أن أجده على الخريطة."),

    // ===== جمل من Crossword Exercise 4 =====
    ItemCard(english: "The end of something like a table or cliff is an edge.", arabic: "نهاية شيء مثل طاولة أو جرف هي حافة."),
    ItemCard(english: "California is in the western part of the US.", arabic: "كاليفورنيا في الجزء الغربي من الولايات المتحدة."),
    ItemCard(english: "I always eat local fruit.", arabic: "أنا دائماً آكل فاكهة محلية."),
    ItemCard(english: "To wait for something you know you will get is to expect.", arabic: "انتظار شيء تعرف أنك ستحصل عليه هو أن تتوقع."),
    ItemCard(english: "What cars and buses have so they can drive on the road are wheels.", arabic: "ما تمتلكه السيارات والباصات لتسير على الطريق هي العجلات."),
    ItemCard(english: "What the sun does every day is shine.", arabic: "ما تفعله الشمس كل يوم هو الإشراق."),
    ItemCard(english: "Toughness is strength.", arabic: "الصلابة هي القوة."),
    ItemCard(english: "Jennifer could not explain why she was late for class.", arabic: "جينيفر لم تستطع أن تشرح لماذا تأخرت عن الحصة."),

    // ===== جمل Idiom =====
    ItemCard(english: "My friends make a big deal about which table we get in a restaurant. That's much ado about nothing as long as the food will be the same.", arabic: "أصدقائي يعطون الأمر أكبر من حجمه بشأن أي طاولة نجلس في المطعم. هذا الكثير من اللفظ عن لا شيء طالما أن الطعام سيكون نفسه."),

    // ===== إضافات - جمل مع Native =====
    ItemCard(english: "She is a native of Egypt.", arabic: "هي مواطنة من مصر."),
    ItemCard(english: "He is a native speaker of English.", arabic: "هو متحدث أصلي للإنجليزية."),
    ItemCard(english: "The native people of the island are very friendly.", arabic: "السكان الأصليون للجزيرة ودودون جداً."),
    ItemCard(english: "I am a native of this city.", arabic: "أنا من سكان هذه المدينة الأصليين."),

    // ===== إضافات - جمل مع Smoke =====
    ItemCard(english: "The smoke from the fire filled the room.", arabic: "الدخان من الحريق ملأ الغرفة."),
    ItemCard(english: "There was a lot of smoke coming from the kitchen.", arabic: "كان هناك الكثير من الدخان يخرج من المطبخ."),
    ItemCard(english: "The smoke made it hard to breathe.", arabic: "الدخان جعل التنفس صعباً."),
    ItemCard(english: "Don't smoke inside the building.", arabic: "لا تدخن داخل المبنى."),

    // ===== إضافات - جمل مع Curious =====
    ItemCard(english: "I'm curious to know what happened.", arabic: "أنا فضولي لمعرفة ما حدث."),
    ItemCard(english: "Children are naturally curious about everything.", arabic: "الأطفال بطبعهم فضوليون تجاه كل شيء."),
    ItemCard(english: "She was curious about the new student.", arabic: "كانت فضولية بشأن الطالب الجديد."),
    ItemCard(english: "Don't be too curious about other people's business.", arabic: "لا تكن فضولياً جداً في شؤون الآخرين."),

    // ===== إضافات - جمل مع Edge =====
    ItemCard(english: "Don't stand near the edge of the roof.", arabic: "لا تقف قرب حافة السطح."),
    ItemCard(english: "She sat on the edge of the bed.", arabic: "هي جلست على حافة السرير."),
    ItemCard(english: "The cup is on the edge of the table.", arabic: "الكوب على حافة الطاولة."),
    ItemCard(english: "He walked along the edge of the river.", arabic: "هو مشى على طول حافة النهر."),

    // ===== إضافات - جمل مع Crowd =====
    ItemCard(english: "A large crowd gathered in the square.", arabic: "حشد كبير تجمع في الساحة."),
    ItemCard(english: "The crowd cheered for the team.", arabic: "الجمهور هتف للفريق."),
    ItemCard(english: "I don't like being in a big crowd.", arabic: "لا أحب التواجد في حشد كبير."),
    ItemCard(english: "The crowd was very quiet during the show.", arabic: "كان الجمهور هادئاً جداً خلال العرض."),

    // ===== إضافات - جمل مع Local =====
    ItemCard(english: "I buy vegetables from the local market.", arabic: "أشتري الخضروات من السوق المحلي."),
    ItemCard(english: "The local food is delicious.", arabic: "الطعام المحلي لذيذ."),
    ItemCard(english: "He is a local artist.", arabic: "هو فنان محلي."),
    ItemCard(english: "We visited a local school.", arabic: "زرنا مدرسة محلية."),

    // ===== إضافات - جمل مع Explain =====
    ItemCard(english: "Can you explain this to me?", arabic: "هل يمكنك شرح هذا لي؟"),
    ItemCard(english: "The teacher explained the lesson clearly.", arabic: "المعلم شرح الدرس بوضوح."),
    ItemCard(english: "He explained why he was late.", arabic: "هو شرح لماذا تأخر."),
    ItemCard(english: "I will explain the rules of the game.", arabic: "سأشرح قواعد اللعبة."),

    // ===== إضافات - جمل مع Suggest =====
    ItemCard(english: "I suggest we go to the beach.", arabic: "أقترح أن نذهب إلى الشاطئ."),
    ItemCard(english: "She suggested a good restaurant for dinner.", arabic: "هي اقترحت مطعماً جيداً للعشاء."),
    ItemCard(english: "The doctor suggested I rest for a week.", arabic: "الطبيب اقترح أن أستريح لأسبوع."),
    ItemCard(english: "Can you suggest a good book?", arabic: "هل يمكنك اقتراح كتاب جيد؟"),

    // ===== إضافات - جمل مع Tour =====
    ItemCard(english: "We went on a tour of the city.", arabic: "ذهبنا في جولة في المدينة."),
    ItemCard(english: "The museum tour was very interesting.", arabic: "جولة المتحف كانت ممتعة جداً."),
    ItemCard(english: "They took a tour of the ancient castle.", arabic: "هم أخذوا جولة في القلعة القديمة."),
    ItemCard(english: "I want to take a tour of Europe next summer.", arabic: "أريد أخذ جولة في أوروبا الصيف القادم."),

    // ===== إضافات - جمل مع Avenue / Road =====
    ItemCard(english: "The avenue is lined with trees.", arabic: "الشارع مصفوف بالأشجار."),
    ItemCard(english: "My grandmother lives on a quiet avenue.", arabic: "جدتي تسكن في شارع هادئ."),
    ItemCard(english: "This road leads to the village.", arabic: "هذا الطريق يؤدي إلى القرية."),
    ItemCard(english: "Which avenue is the restaurant on?", arabic: "في أي شارع يقع المطعم؟"),

    // ===== إضافات - جمل مع Native / Nation =====
    ItemCard(english: "She is a native of Canada.", arabic: "هي مواطنة من كندا."),
    ItemCard(english: "He is a native of Russia.", arabic: "هو مواطن من روسيا."),
    ItemCard(english: "The nation celebrated its independence.", arabic: "الأمة احتفلت باستقلالها."),
    ItemCard(english: "Our nation is rich in history.", arabic: "أمتنا غنية بالتاريخ."),

    // ===== إضافات - جمل مع Tradition =====
    ItemCard(english: "It's a family tradition to eat together on Fridays.", arabic: "من تقليد العائلة أن نأكل معاً أيام الجمعة."),
    ItemCard(english: "This tradition is hundreds of years old.", arabic: "هذا التقليد عمره مئات السنين."),
    ItemCard(english: "They follow the traditions of their ancestors.", arabic: "هم يتبعون تقاليد أجدادهم."),
    ItemCard(english: "Every country has its own traditions.", arabic: "كل دولة لها تقاليدها الخاصة."),

    // ===== إضافات - جمل متنوعة =====
    ItemCard(english: "The smoke made me cough.", arabic: "الدخان جعلني أسعل."),
    ItemCard(english: "She was curious about the tour.", arabic: "كانت فضولية بشأن الجولة."),
    ItemCard(english: "He disappeared in the crowd.", arabic: "هو اختفى في الحشد."),
    ItemCard(english: "She works as a guide for the hotel.", arabic: "هي تعمل كمرشدة للفندق."),
    ItemCard(english: "This helpful machine saves time.", arabic: "هذه الآلة المفيدة توفر الوقت."),
    ItemCard(english: "Hans burned his food, causing a lot of smoke.", arabic: "هانز حرق طعامه، مما سبب الكثير من الدخان."),
    ItemCard(english: "I cannot imagine how big the crowd will be.", arabic: "لا أستطيع تخيل كم سيكون الحشد كبيراً."),
    ItemCard(english: "I viewed the street below from the edge of the roof.", arabic: "شاهدت الشارع بالأسفل من حافة السطح."),
    ItemCard(english: "We discovered a restaurant which serves food grown by local farmers.", arabic: "اكتشفنا مطعماً يقدم طعاماً مزروعاً من مزارعين محليين."),
    ItemCard(english: "Ben tried to explain the math problem.", arabic: "بن حاول أن يشرح مسألة الرياضيات."),
    ItemCard(english: "Bree rubbed her head after she fell.", arabic: "بري فركت رأسها بعد أن سقطت."),
    ItemCard(english: "The tour included a visit to a small village.", arabic: "الجولة شملت زيارة إلى قرية صغيرة."),
    ItemCard(english: "Can you suggest a good restaurant for fish?", arabic: "هل يمكنك اقتراح مطعم جيد للسمك؟"),
    ItemCard(english: "Which avenue does your grandmother live on?", arabic: "في أي شارع تسكن جدتك؟"),
    ItemCard(english: "The end of something like a table or cliff is an edge.", arabic: "نهاية شيء مثل طاولة أو جرف هي حافة."),
    ItemCard(english: "California is in the western part of the US.", arabic: "كاليفورنيا في الجزء الغربي من الولايات المتحدة."),
    ItemCard(english: "I always eat local fruit.", arabic: "أنا دائماً آكل فاكهة محلية."),
    ItemCard(english: "To wait for something you know you will get is to expect.", arabic: "انتظار شيء تعرف أنك ستحصل عليه هو أن تتوقع."),
    ItemCard(english: "What cars and buses have are wheels.", arabic: "ما تمتلكه السيارات والباصات هي العجلات."),
    ItemCard(english: "What the sun does every day is shine.", arabic: "ما تفعله الشمس كل يوم هو الإشراق."),
    ItemCard(english: "Toughness is strength.", arabic: "الصلابة هي القوة."),
    ItemCard(english: "Jennifer could not explain why she was late for class.", arabic: "جينيفر لم تستطع أن تشرح لماذا تأخرت عن الحصة."),
  ];

  @override
  Widget build(BuildContext context) {
    return GenericListScreen(
      title: "Episode 10 - جميع الجمل",
      items: sentences,
      primaryColor: ColorManager.celestial2,
      secondaryColor: Color(0xFF203A43),
    );
  }
}


