class FinalReviewPart1SentencesScreen extends StatelessWidget {
  final List<ItemCard> sentences = [
    // ===================== الدرس 1: Awful Smell =====================
    ItemCard(english: "Matt hates the awful smell coming from his shoes.", arabic: "مات يكره الرائحة البشعة الخارجة من حذائه."),
    ItemCard(english: "Jack's hair looks really crazy, and he has an interview today!", arabic: "شعر جالك يبدو غريباً جداً، وهو لديه مقابلة عمل اليوم!"),
    ItemCard(english: "I'll give you a thousand dollars if you eat this huge burger.", arabic: "سأعطيك ألف دولار إذا أكلت هذا البرجر الضخم."),
    ItemCard(english: "Lewis's choice of hair color is quite odd.", arabic: "اختيار لويس للون الشعر غريب جداً."),
    ItemCard(english: "I don't regret the 18 years I was married to Nancy.", arabic: "أنا لست نادماً على الـ 18 عام التي كنت فيها متزوجاً نانسي."),
    ItemCard(english: "Max is the toughest man in our city.", arabic: "ماكس هو أقوى رجل في مدينتنا."),
    ItemCard(english: "This is your last chance.", arabic: "هذه هي فرصتك الأخيرة."),
    ItemCard(english: "He intends to eat only healthy food from now on.", arabic: "هو ينوي أن يأكل فقط طعاماً صحياً من الآن فصاعداً."),
    ItemCard(english: "It was a mistake to tell him the news. His reaction was very bad.", arabic: "كان من الخطأ إخباره بالأخبار، كانت ردة فعله سيئة للغاية."),
    ItemCard(english: "He scored the winning goal at last night's game.", arabic: "هو سجل هدف الفوز في مباراة الأمس."),
    ItemCard(english: "There is nothing worse than cleaning the floor.", arabic: "ليس هناك أسوأ من تنظيف الأرضية."),
    ItemCard(english: "I'm between the devil and the deep blue sea.", arabic: "أنا بين إختيارين كليهما مر."),
    ItemCard(english: "If I call her, she will yell at me and if I don't she will think I'm ignoring her.", arabic: "إذا اتصلت بها، ستصرخ فيّ وإذا لم أفعل ستظن أني أتجاهلها."),
    ItemCard(english: "To settle an old score.", arabic: "ليُسوّي حساباً قديماً."),
    ItemCard(english: "This exam was really tough.", arabic: "هذا الامتحان كان صعباً حقاً."),
    ItemCard(english: "Life is tough, but so are you.", arabic: "الحياة صعبة، ولكنك أيضاً قوي."),
    ItemCard(english: "Give me one more chance.", arabic: "أعطني فرصة أخرى."),
    ItemCard(english: "The meeting is in the main hall.", arabic: "الاجتماع في القاعة الرئيسية."),
    ItemCard(english: "Call the police immediately.", arabic: "اتصل بالشرطة فوراً."),
    ItemCard(english: "I intend to travel next month.", arabic: "أنوي السفر الشهر القادم."),
    ItemCard(english: "Don't mention it.", arabic: "لا تذكر ذلك."),
    ItemCard(english: "His reaction surprised everyone.", arabic: "ردة فعله فاجأت الجميع."),
    ItemCard(english: "He scored two goals in the match.", arabic: "هو سجل هدفين في المباراة."),
    ItemCard(english: "The situation is getting worse.", arabic: "الوضع يزداد سوءاً."),
    ItemCard(english: "It could be worse.", arabic: "كان يمكن أن يكون أسوأ."),
    ItemCard(english: "This task is a piece of cake.", arabic: "هذه المهمة سهلة جداً."),
    ItemCard(english: "You hit the nail on the head.", arabic: "لقد أصبت كبد الحقيقة."),
    ItemCard(english: "I'm feeling under the weather today.", arabic: "أشعر أنني متوعك اليوم."),
    ItemCard(english: "He visits us once in a blue moon.", arabic: "هو يزورنا نادراً جداً."),

    // ===================== الدرس 2: A Very Bad Day =====================
    ItemCard(english: "Nancy regrets saying mean things to her brother when he broke her favorite pot.", arabic: "نانسي تندم على قول أشياء لئيمة لأخيها عندما كسر قدرها المفضل."),
    ItemCard(english: "Would you pour me a tall glass of chocolate milk, please?", arabic: "هل تصب لي كوباً طويلاً من حليب الشوكولاتة، من فضلك؟"),
    ItemCard(english: "Why did you throw your cat into the water? Are you crazy?", arabic: "لماذا رميت قطتك في الماء؟ هل أنت مجنون؟"),
    ItemCard(english: "Could you wait a moment? I have to shut the window before we go out.", arabic: "هل يمكنك الانتظار لحظة؟ يجب أن أغلق النافذة قبل أن نخرج."),
    ItemCard(english: "You should not steal your friend's toys. It is wrong.", arabic: "لا يجب أن تسرق ألعاب صديقك. هذا خطأ."),
    ItemCard(english: "Julie forgot to mention that her brother was in the movie.", arabic: "جولي نسيت أن تذكر أن أخاها كان في الفيلم."),
    ItemCard(english: "The boy intended to run in the race, but he broke his leg.", arabic: "الولد كان ينوي الجري في السباق، لكنه كسر ساقه."),
    ItemCard(english: "Oh, I didn't want extra cheese on my pizza. Can you take it off, please?", arabic: "أوه، لم أرد جبنة إضافية على البيتزا. هل يمكنك نزعها، من فضلك؟"),
    ItemCard(english: "Mike! You need to stop fighting with your brother immediately.", arabic: "مايك! يجب أن تتوقف عن القتال مع أخيك فوراً."),
    ItemCard(english: "Chris got the ball and scored the winning goal. Everyone cheered for him.", arabic: "كريس حصل على الكرة وسجل هدف الفوز. الجميع هتف له."),
    ItemCard(english: "Today was awful. I intended to go to soccer practice.", arabic: "اليوم كان بشعاً. كنت أنوي الذهاب إلى تمرين كرة القدم."),
    ItemCard(english: "The coach mentioned that he wanted me to score more points.", arabic: "المدرب ذكر أنه يريدني أن أسجل نقاطاً أكثر."),
    ItemCard(english: "I needed extra practice. I did not get the chance to practice.", arabic: "كنت أحتاج تمريناً إضافياً. لم أحصل على الفرصة للتدرب."),
    ItemCard(english: "Someone stole my soccer shoes! I searched everywhere but could not find them.", arabic: "شخص ما سرق حذاء كرة القدم الخاص بي! بحثت في كل مكان لكن لم أستطع إيجاده."),
    ItemCard(english: "I felt even worse because they were new. I really regretted bringing them.", arabic: "شعرت بأسوأ لأنها كانت جديدة. ندمت حقاً على إحضارها."),
    ItemCard(english: "When I saw that the shoes were missing, I went to my coach immediately.", arabic: "عندما رأيت أن الحذاء مفقود، ذهبت إلى مدربي فوراً."),
    ItemCard(english: "His reaction was calm. He did not think it was odd for someone to steal my shoes.", arabic: "ردة فعله كانت هادئة. لم يعتقد أنه غريب أن يسرق شخص حذائي."),
    ItemCard(english: "He said it happened a lot, and he would find the thief and make him return my shoes.", arabic: "قال إنها تحدث كثيراً، وسيجد اللص ويجعله يُرجع حذائي."),
    ItemCard(english: "I watched my team practice. Our players are not huge, but we are all tough.", arabic: "شاهدت فريقي يتدرب. لاعبونا ليسوا ضخاماً، لكننا كلنا أقوياء."),
    ItemCard(english: "I cannot wait to get my shoes back and play again.", arabic: "لا أستطيع الانتظار لاستعادة حذائي واللعب مرة أخرى."),
    ItemCard(english: "Ryan is a big and tough basketball player. He is the best on our team.", arabic: "رايان لاعب كرة سلة كبير وقوي. هو الأفضل في فريقنا."),
    ItemCard(english: "The accident on the busy road was awful. Many people were hurt.", arabic: "الحادث على الطريق المزدحم كان بشعاً. كثير من الناس أصيبوا."),
    ItemCard(english: "Maggie found several odd insects on the ground on her way home.", arabic: "ماجي وجدت عدة حشرات غريبة على الأرض في طريقها للمنزل."),
    ItemCard(english: "We cannot take the stairs to the top of the huge building.", arabic: "لا يمكننا صعود السلالم إلى قمة المبنى الضخم."),
    ItemCard(english: "The thief used a long rope to get down from the house.", arabic: "اللص استخدم حبلاً طويلاً لينزل من المنزل."),

    // ===================== الدرس 3: Bit & Common =====================
    ItemCard(english: "I broke the chocolate into bits so I could share it with my friends.", arabic: "كسرت الشوكولاتة إلى أجزاء لكي أستطيع مشاركتها مع أصدقائي."),
    ItemCard(english: "Colds are quite common in the winter.", arabic: "نزلات البرد شائعة جداً في فصل الشتاء."),
    ItemCard(english: "I intend to have a healthier diet by eating more fruit.", arabic: "أنوي اتباع نظام غذائي صحي من خلال تناول المزيد من الفاكهة."),
    ItemCard(english: "They stay fit by running whenever possible.", arabic: "يظلون لائقين عن طريق الجري كلما كان ذلك ممكناً."),
    ItemCard(english: "She has little money and must limit how much she spends.", arabic: "لديها القليل من المال ويجب أن تحدد من المبلغ الذي تنفقه."),
    ItemCard(english: "Playing sports is a good way to get physical exercise.", arabic: "ممارسة الرياضة وسيلة جيدة للحصول على تمارين جسدية."),
    ItemCard(english: "The police found evidence that Jerry was the thief.", arabic: "عثرت الشرطة على دليل على أن جيري كان اللص."),
    ItemCard(english: "There is a nice house for sale in my neighborhood.", arabic: "هناك منزل جميل للبيع في الحي الذي أسكن فيه."),
    ItemCard(english: "Make sure to use the right amount of oil to fry the food.", arabic: "تأكد من استخدام الكمية المناسبة من الزيت لقلي الطعام."),
    ItemCard(english: "The new cure made John feel better almost immediately.", arabic: "العلاج الجديد جعل جون يشعر بتحسن على الفور تقريباً."),
    ItemCard(english: "A disease made the tree's leaves turn brown.", arabic: "مرض جعل أوراق الشجرة تتحول إلى اللون البني."),
    ItemCard(english: "The symbol on the bottle says that it is poison.", arabic: "الرمز على الزجاجة يقول إنه سم."),
    ItemCard(english: "Bakeries usually sell several different types of bread.", arabic: "عادةً ما تبيع المخابز عدة أنواع مختلفة من الخبز."),
    ItemCard(english: "We saw a serious car accident this afternoon.", arabic: "شاهدنا حادث سيارة خطير بعد ظهر هذا اليوم."),
    ItemCard(english: "If you often have awful headaches, you should get medical help.", arabic: "إذا كنت تعاني من صداع فظيع في كثير من الأحيان، يفضل أن تحصل على مساعدة طبية."),
    ItemCard(english: "When getting ready for a trip, take only what is necessary.", arabic: "عند الاستعداد لرحلة، خذ فقط ما هو ضروري."),
    ItemCard(english: "The store reduced its prices on everything.", arabic: "المتجر خفض أسعاره على كل شيء."),
    ItemCard(english: "My father supplies carrots to restaurants in our town.", arabic: "والدي يزود مطاعم مدينتنا بالجزر."),

    // ===================== الدرس 4: Episode 4 =====================
    ItemCard(english: "Junk food includes candy, potato chips, and cookies.", arabic: "الوجبات السريعة تشمل الحلوى ورقائق البطاطس والبسكويت."),
    ItemCard(english: "Eating this type of food too much is like eating poison.", arabic: "تناول هذا النوع من الطعام بكثرة يشبه أكل السم."),
    ItemCard(english: "Today, it is common for kids to weigh too much and be less fit than children in the past.", arabic: "اليوم، من الشائع أن يزن الأطفال أكثر من اللازم ويكونوا أقل ليونة من الأطفال في الماضي."),
    ItemCard(english: "That is because their diets are worse than they used to be.", arabic: "هذا لأن أنظمتهم الغذائية أسوأ مما كانت عليه."),
    ItemCard(english: "This is a serious problem. Evidence shows that bad diets can cause diseases that have no cure now.", arabic: "هذه مشكلة خطيرة. يُظهر الدليل أن الأنظمة الغذائية السيئة يمكن أن تسبب أمراضاً ليس لها علاج الآن."),
    ItemCard(english: "We can reduce the amount of soda we drink; soda is mostly sugar.", arabic: "يمكننا تقليل كمية الصودا التي نشربها؛ الصودا في الغالب سكر."),
    ItemCard(english: "It does not supply our bodies with anything necessary.", arabic: "إنها لا تزود أجسامنا بأي شيء ضروري."),
    ItemCard(english: "We should also limit snacks like potato chips.", arabic: "يجب أيضاً أن نحد من الوجبات الخفيفة مثل رقائق البطاطس."),
    ItemCard(english: "You can eat a bit of junk food sometimes. Just do not eat it every day!", arabic: "يمكنك أكل قليل من الوجبات السريعة أحياناً. فقط لا تأكلها كل يوم!"),
    ItemCard(english: "Some US schools have stopped the sale of soda at lunch.", arabic: "بعض المدارس الأمريكية أوقفت بيع الصودا عند الغداء."),
    ItemCard(english: "We decided to get married in July but it's not yet carved in stone.", arabic: "قررنا أن نتزوج في يوليو ولكن الأمر ليس منقوشاً على الحجر بعد."),
    ItemCard(english: "Who will carve the chicken?", arabic: "من سيقطع الدجاجة؟"),
    ItemCard(english: "The plan is not carved in stone yet. We can still change it.", arabic: "الخطة ليست منقوشة على الحجر بعد. لا يزال بإمكاننا تغييرها."),
    ItemCard(english: "He carved a beautiful sculpture from wood.", arabic: "هو نحت تمثالاً جميلاً من الخشب."),
    ItemCard(english: "I like a bit of sugar in my tea.", arabic: "أحب قليلاً من السكر في شايي."),
    ItemCard(english: "People use poison to kill insects.", arabic: "الناس يستخدمون السم لقتل الحشرات."),
    ItemCard(english: "Do your parents limit how much candy you eat?", arabic: "هل يحدد والداك كمية الحلوى التي تأكلها؟"),
    ItemCard(english: "People usually have more physical problems as they get older.", arabic: "الناس عادةً يعانون من مشاكل جسدية أكثر كلما تقدموا في العمر."),
    ItemCard(english: "Liam wants to get fit so he can play on the soccer team.", arabic: "ليام يريد أن يصبح لائقاً بدنياً حتى يتمكن من اللعب في فريق كرة القدم."),
    ItemCard(english: "Carrie made \$80 from the sale of her bike.", arabic: "كاري جمعت 80 دولاراً من بيع دراجتها."),
    ItemCard(english: "Brown is the most common eye color in the world.", arabic: "البني هو أكثر لون عين شائع في العالم."),
    ItemCard(english: "There is a lot of evidence that the Earth is getting warmer.", arabic: "هناك الكثير من الأدلة على أن الأرض تزداد حرارة."),
    ItemCard(english: "Megan forgot to mention what type of ice cream to buy.", arabic: "ميغان نسيت أن تذكر نوع الآيس كريم الذي يجب شراؤه."),
    ItemCard(english: "The diet of an elephant does not include meat.", arabic: "نظام غذاء الفيل لا يشمل اللحوم."),
    ItemCard(english: "Plants supply a lot of our food.", arabic: "النباتات تزودنا بالكثير من طعامنا."),
    ItemCard(english: "We are trying to reduce the amount of TV we watch.", arabic: "نحن نحاول تقليل كمية التلفاز التي نشاهدها."),
    ItemCard(english: "Using too much energy causes serious problems for the environment.", arabic: "استخدام الكثير من الطاقة يسبب مشاكل خطيرة للبيئة."),
    ItemCard(english: "Germany produces a lot of popular cars.", arabic: "ألمانيا تنتج الكثير من السيارات الشهيرة."),
    ItemCard(english: "Ellen was the best source of ideas in our group.", arabic: "إلين كانت أفضل مصدر للأفكار في مجموعتنا."),
  ];

  @override
  Widget build(BuildContext context) {
    return GenericListScreen(
      title: "Final Review Part 1 - Sentences",
      items: sentences,
      primaryColor: ColorManager.celestial2,
      secondaryColor: Color(0xFF203A43),
    );
  }
}



