    ItemCard(english: "She needs to limit the items, she is packing in her suitcase.", arabic: "هي تحتاج إلى الحد من الأشياء التي تقوم بتعبئتها في حقيبتها."),
    ItemCard(english: "Gabriella prefers to eat fresh fruit instead of junk food.", arabic: "غابرييلا تفضل أكل الفاكهة الطازجة بدلاً من الوجبات السريعة."),
